{
	"name": "@rizal72/oc-coffee",
	"version": "0.2.4",
	"type": "module",
	"description": "Keeps the Mac awake while the agent works: the server owns the level, the terminal draws a cup badge, the desktop a cup in the session header",
	"repository": {
		"type": "git",
		"url": "git+https://github.com/rizal72/opencode-plugins.git"
	},
	"license": "MIT",
	"files": [
		"*.ts",
		"!*.test.ts",
		"tui.js",
		"README.md",
		"dist"
	],
	"keywords": [
		"opencode",
		"opencode-plugin",
		"macos",
		"caffeinate"
	],
	"publishConfig": {
		"access": "public"
	},
	"exports": {
		".": "./index.ts",
		"./tui": "./tui.js",
		"./rpc": "./rpc.ts",
		"./gui-experimental": "./dist/gui-experimental.cjs"
	}
}
